window.docContents[249].resolve({"/Imp/#imp-notations":{"contents":"To make Imp programs easier to read and write, we introduce some notations.You do not need to understand exactly what these declarations do. Briefly, though,\nhere is how the two blocks below fit together:* The declare_syntax_cat directive adds a new non-terminal to Lean's grammar, called\n  imp_aexp. We'll add additional non-terminals further below.* Each syntax directive defines a grammar production. Seven of them build the\n  imp_aexp category itself: the first two make a numeric literal and an\n  identifier into an imp_aexp, the next three build larger expressions (with\n  annotations that fix precedence and associativity), and the last two are\n  parentheses for grouping and ~, the escape back to Lean. The eighth,\n  aexp { … }, is a production of Lean's own term category — it is what lets\n  an Imp expression appear in ordinary Lean code.* ~e splices an already-elaborated Lean term e into Imp syntax. We will rarely need\n  to use this in this book, however. By convention, our notation always treats\n  identifiers starting with capital Latin letters as being literal names in Imp.\n  Thus X, Y, and Z are Imp variables. Meanwhile, names beginning with\n  lowercase Latin letters (like a or c) are treated as Lean variables. This will\n  be useful later when we need to write theorems about Imp programs. We only need to use\n  the ~ when we want to insert a larger Lean expression into an Imp term. We'll\n  point out examples of this when they occur.* Finally, macro_rules is used to translate each production of the imp_aexp non-terminal\n  into a Lean expression.Boolean expressions and, later, commands follow this same pattern exactly, so\ntheir declarations are collapsed where they appear: open one if you want to see\nthe pattern repeated, and skip it otherwise.\n\n/-- Arithmetic expressions of Imp -/\ndeclare_syntax_cat imp_aexp\n/-- Numeric literal -/\nsyntax:max num : imp_aexp\n/-- `Ident` or Lean identifier -/\nsyntax:max ident : imp_aexp\n/-- Addition -/\nsyntax:65 imp_aexp:65 \" + \" imp_aexp:66 : imp_aexp\n/-- Subtraction -/\nsyntax:65 imp_aexp:65 \" - \" imp_aexp:66 : imp_aexp\n/-- Multiplication -/\nsyntax:70 imp_aexp:70 \" * \" imp_aexp:71 : imp_aexp\n/-- Parentheses for grouping -/\nsyntax:max \"(\" imp_aexp \")\" : imp_aexp\n/-- Escape to Lean -/\nsyntax:max \"~\" term:max : imp_aexp\n\n/-- Embed an Imp arithmetic expression into a Lean term -/\nsyntax:80 \"aexp \" \"{\" imp_aexp \"}\" : term\nnamespace Imp.Elab\n\nopen Lean Elab Term Meta\n\ndef withSourceInfoOf {kind : Name} (ref : Syntax) (stx : TSyntax kind)\n    (canonical := true) : TSyntax kind :=\n  let info := SourceInfo.fromRef ref (canonical := canonical)\n  ⟨stx.raw.setInfo info⟩\n\ndef isGreek (c : Char) : Bool :=\n  let n := c.val.toNat\n  decide (\n    (0x0370 ≤ n ∧ n ≤ 0x03ff) ∨\n    (0x1f00 ≤ n ∧ n ≤ 0x1fff))\n\ninductive IdentKind where\n  | object\n  | metavar\n  deriving BEq\n\ndef classifyIdent? (id : Lean.Ident) : Option (IdentKind × String) := do\n  let Name.str .anonymous s := id.getId.eraseMacroScopes\n    | failure\n  if s.isEmpty || s.contains '.' then failure\n  let c := s.front\n  if c.isUpper then return (.object, s)\n  else if c.isLower || isGreek c then return (.metavar, s)\n  else failure\n\ndef mkObjectIdentFrom (ref : Syntax) (name : String) : Lean.Ident :=\n  mkIdentFrom ref (Name.mkSimple name)\n\ndef elabMetavarOnlyIdent (what : String) (expectedType : Term) (x : Lean.Ident) :\n    MacroM Term := do\n  match classifyIdent? x with\n  | some (.metavar, _) => `(($x : $expectedType))\n  | some (.object, name) =>\n      Macro.throwErrorAt x\n        s!\"no Imp {what} named `{name}`; capitalized bare names are always \\\nread as Imp identifiers — use a lowercase name or escape with `~` to refer to Lean name\"\n  | none => Macro.throwErrorAt x \"invalid bare identifier\"\n\nmacro_rules\n  | `(aexp { $exp:imp_aexp }) => do\n    let stx ← match exp with\n      | `(imp_aexp| $n:num) => ``(Aexp.num $n)\n      | `(imp_aexp| ~$e:term) => ``(($e : Aexp))\n      | `(imp_aexp| $x:ident) =>\n          match classifyIdent? x with\n          | some (.object, name) =>\n              let nameLit : Term := ⟨Syntax.mkStrLit name⟩\n              ``(Aexp.id $nameLit)\n          | some (.metavar, _) => ``(($x : Aexp))\n          | none => Macro.throwErrorAt x \"invalid bare identifier\"\n      | `(imp_aexp| $a + $b) => ``(Aexp.plus (aexp {$a}) (aexp {$b}))\n      | `(imp_aexp| $a - $b) => ``(Aexp.minus (aexp {$a}) (aexp {$b}))\n      | `(imp_aexp| $a * $b) => ``(Aexp.mult (aexp {$a}) (aexp {$b}))\n      | `(imp_aexp| ($a)) => ``(aexp {$a})\n      | _ => Lean.Macro.throwUnsupported\n    return withSourceInfoOf exp stx\n\nend Imp.Elab\n\n\n\n\n/-- Boolean expressions of Imp -/\ndeclare_syntax_cat imp_bexp\n/-- Boolean literal (`true` or `false`) and Lean identifier -/\nsyntax:max ident : imp_bexp\n/-- Equality of arithmetic expressions -/\nsyntax:50 imp_aexp:51 \" = \" imp_aexp:51 : imp_bexp\n/-- Disequality of arithmetic expressions -/\nsyntax:50 imp_aexp:51 \" ≠ \" imp_aexp:51 : imp_bexp\n/-- Less than or equal -/\nsyntax:50 imp_aexp:51 \" ≤ \" imp_aexp:51 : imp_bexp\n/-- Greater than -/\nsyntax:50 imp_aexp:51 \" > \" imp_aexp:51 : imp_bexp\n/-- Boolean negation -/\nsyntax:70 \"¬ \" imp_bexp:70 : imp_bexp\n/-- Boolean conjunction (right associative) -/\nsyntax:35 imp_bexp:36 \" ∧ \" imp_bexp:35 : imp_bexp\n/-- Parentheses for grouping -/\nsyntax:max \"(\" imp_bexp \")\" : imp_bexp\n/-- Escape to Lean -/\nsyntax:max \"~\" term:max : imp_bexp\n\n/-- Embed an Imp boolean expression into a Lean term -/\nsyntax:80 \"bexp \" \"{\" imp_bexp \"}\" : term\n\n\nnamespace Imp.Elab\n\nopen Lean\n\nmacro_rules\n  | `(bexp { $exp:imp_bexp }) => do\n    let stx ← match exp with\n      | `(imp_bexp| true) => ``(Bexp.bool true)\n      | `(imp_bexp| false) => ``(Bexp.bool false)\n      | `(imp_bexp| $x:ident) => do elabMetavarOnlyIdent \"boolean\" (← ``(Bexp)) x\n      | `(imp_bexp| ~$e:term) => ``(($e : Bexp))\n      | `(imp_bexp| $a:imp_aexp = $b:imp_aexp) => ``(Bexp.eq (aexp {$a}) (aexp {$b}))\n      | `(imp_bexp| $a:imp_aexp ≠ $b:imp_aexp) => ``(Bexp.neq (aexp {$a}) (aexp {$b}))\n      | `(imp_bexp| $a:imp_aexp ≤ $b:imp_aexp) => ``(Bexp.le (aexp {$a}) (aexp {$b}))\n      | `(imp_bexp| $a:imp_aexp > $b:imp_aexp) => ``(Bexp.gt (aexp {$a}) (aexp {$b}))\n      | `(imp_bexp| ¬ $b:imp_bexp) => ``(Bexp.not (bexp {$b}))\n      | `(imp_bexp| $b₁:imp_bexp ∧ $b₂:imp_bexp) => ``(Bexp.and (bexp {$b₁}) (bexp {$b₂}))\n      | `(imp_bexp| ($b:imp_bexp)) => ``(bexp {$b})\n      | _ => Macro.throwUnsupported\n    return withSourceInfoOf exp stx\n\nend Imp.Elab\n\n\n#check aexp { 3 + (X * 2) }\n#check bexp { true ∧ ¬(X ≤ 4) }\n\n\n","context":"Hoare Logic\u0009Imp: Simple Imperative Programs\u0009Expressions With Variables","header":"3.1.3. Notations","id":"/Imp/#imp-notations"}});